1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	/**
7	 * Derives an owner's numeric 'membershipLevel', assigned on create. Kept out of
8	 * {@link OwnerMapper} so MapStruct does not mistake it for an implicit property
9	 * mapping method.
10	 */
11	public final class MembershipLevelResolver {
12	
13	    /** Highest level attainable without tenure; level 4 is gated on tenure. */
14	    private static final int PRE_TENURE_MAX_LEVEL = 3;
15	
16	    /** Highest level attainable at all, once the tenure requirement is met. */
17	    private static final int TENURED_MAX_LEVEL = 4;
18	
19	    /** Tenure, in days, that must be exceeded before level 4 may be awarded. */
20	    private static final int TENURE_THRESHOLD_DAYS = 365;
21	
22	    /** A household of this many members (or more) earns the GOLD (level 4) factor. */
23	    private static final int GOLD_HOUSEHOLD_SIZE = 3;
24	
25	    private MembershipLevelResolver() {
26	    }
27	
28	    /**
29	     * Returns the membership level for an owner. Starts at 1, gains 1 when an
30	     * email is present (non-blank), gains 1 when the owner's name was unique on
31	     * create ({@code namesakeCount} is 0) and gains 1 when the owner belongs to a
32	     * household of three or more members (the GOLD factor).
33	     *
34	     * <p>Level 4 is reserved for tenured owners: it is awarded only when the owner
35	     * has been registered for more than 365 days. Below that tenure the level is
36	     * capped at 3, so a newly created owner (zero tenure) never exceeds level 3 even
37	     * with an email, a unique name and a three-member household.
38	     *
39	     * @param email                the owner's email, may be {@code null}
40	     * @param namesakeCount        the owner's namesake count, may be {@code null}
41	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
42	     * @param registrationDate     the owner's registration date, may be {@code null}
43	     * @return the membership level, between 1 and 4 inclusive
44	     */
45	    public static int deriveMembershipLevel(String email, Integer namesakeCount,
46	            Integer householdMemberCount, LocalDate registrationDate) {
47	        int level = 1;
48	        if (email != null && !email.isBlank()) {
49	            level++;
50	        }
51	        if (namesakeCount != null && namesakeCount == 0) {
52	            level++;
53	        }
54	        if (householdMemberCount != null && householdMemberCount >= GOLD_HOUSEHOLD_SIZE) {
55	            level++;
56	        }
57	        int maxLevel = hasTenure(registrationDate) ? TENURED_MAX_LEVEL : PRE_TENURE_MAX_LEVEL;
58	        return Math.min(level, maxLevel);
59	    }
60	
61	    /**
62	     * Reports whether an owner's tenure exceeds the level-4 threshold, i.e. it has been more than
63	     * 365 days since {@code registrationDate}. A {@code null} or future registration date counts as
64	     * no tenure.
65	     *
66	     * @param registrationDate the owner's registration date, may be {@code null}
67	     * @return {@code true} when the owner has been registered for more than 365 days
68	     */
69	    private static boolean hasTenure(LocalDate registrationDate) {
70	        if (registrationDate == null) {
71	            return false;
72	        }
73	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_THRESHOLD_DAYS;
74	    }
75	}
