1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.stereotype.Component;
4	
5	/**
6	 * Derives the shared {@code householdId} that every owner in the same household resolves to. The household is keyed on
7	 * the owner's last name and postcode, so the identifier is a pure, deterministic function of those two fields and every
8	 * owner sharing them resolves to the same value automatically, regardless of creation order. Kept here (rather than in
9	 * {@link OwnerMapper} or the REST controller) mirrors {@link IdentityKeyResolver}, {@link LocalityResolver} and
10	 * {@link MembershipLevelResolver} and gives household derivation a single home.
11	 */
12	@Component
13	public class HouseholdResolver {
14	
15	    /**
16	     * Derives a household's stable identifier: the first 12 hex characters of the SHA-256 digest of the normalized
17	     * last name, a {@code '|'} separator and the postcode. The last name is normalized by trimming it, collapsing every
18	     * run of whitespace to a single space and lower-casing it; the postcode is used as given (an empty string when
19	     * none). Being a pure function of the last name and postcode, it is identical for every owner in the same household
20	     * and never changes over time.
21	     *
22	     * @param lastName the household's last name
23	     * @param postcode the household's postcode, may be {@code null}
24	     * @return the household identifier
25	     */
26	    public String deriveHouseholdId(String lastName, String postcode) {
27	        String key = collapseWhitespace(lastName).toLowerCase() + "|" + (postcode == null ? "" : postcode);
28	        return HexDigest.upperHexPrefix(key, 12);
29	    }
30	
31	    /**
32	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
33	     * space. Case is deliberately preserved here; {@link #deriveHouseholdId} lower-cases the result itself.
34	     *
35	     * @param value the raw field value, may be {@code null}
36	     * @return the whitespace-collapsed value, or an empty string when {@code null}
37	     */
38	    public String collapseWhitespace(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.strip().replaceAll("\\s+", " ");
43	    }
44	}
