```java
public static int deriveMembershipLevel(String email, Integer namesakeCount,
        Integer householdMemberCount, LocalDate registrationDate) {
    int level = 1;
    if (email != null && !email.isBlank()) {
        level++;
    }
    if (namesakeCount != null && namesakeCount == 0) {
        level++;
    }
    if (householdMemberCount != null && householdMemberCount >= GOLD_HOUSEHOLD_SIZE) { // GOLD_HOUSEHOLD_SIZE = 3
        level++;
    }
    int maxLevel = hasTenure(registrationDate) ? TENURED_MAX_LEVEL : PRE_TENURE_MAX_LEVEL; // 4 : 3
    return Math.min(level, maxLevel);
}

private static boolean hasTenure(LocalDate registrationDate) {
    if (registrationDate == null) {
        return false;
    }
    return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_THRESHOLD_DAYS; // 365
}
```

